create or replace TABLE KFL_PRODUCTION_CLONE_GCP_MIGRATION_20260608_0800.DBP_DATA.BESCH_LIEF_WG_WUP_2 cluster by (dat_lief_soll)(
	MANDANT_ID NUMBER(38,0) NOT NULL COMMENT 'Der Mandant_2 1 steht im DWH für Deutschland (der Wert 22 aus dem SAP System für Deutschland wird in Wert 1 umgewandelt).',
	WUP_ID NUMBER(38,0) NOT NULL COMMENT 'Nummer des VZ',
	NB_ID NUMBER(38,0) NOT NULL COMMENT 'Im bisherigen System die 4 Stelle der Marktnummer die Nebenbetriebskennziffer',
	LAGERORT_ID VARCHAR(4) NOT NULL COLLATE 'en-ci' COMMENT 'Dieses Feld referenziert die DWH Tabelle Lagerort.',
	DIFF_ID VARCHAR(1) NOT NULL COLLATE 'en-ci' COMMENT 'Wenn eine_2 Lieferposition nicht vollständig beliefert werden kann, wird die Restmenge vom VZ nachgeliefert oder muss vom Markt neu bestellt werden. Diese Information wird auch als Nachlieferkennzeichen bezeichnet.',
	DAT_LIEF_SOLL DATE NOT NULL COMMENT 'Datum, bei dem die Lieferung beim Kunden eingehen soll. Das System kann für den Warenausgang das Lieferdatum aufgrund vordefinierter Zeitschätzungen errechnen.',
	LIEF_TYP_ID VARCHAR(4) NOT NULL COLLATE 'en-ci' COMMENT 'Klassifikation, mit der zwischen verschiedenen Arten der Lieferung unterschieden wird. Die Lieferart bestimmt, wie das System eine_2 Lieferung bearbeitet.',
	VERTR_BELEG_TYP_ID VARCHAR(4) NOT NULL COLLATE 'en-ci' COMMENT 'Dieses Kennzeichen liefert die Information aus welchem Vorgang dieser Vertriebsbeleg generiert wurde, z. B. wurde der Lieferschein aufgrund eines Wareneingangs generiert.',
	WG_ID NUMBER(38,0) NOT NULL COMMENT 'ID der Warengruppe',
	ARTHIERTYP_ID NUMBER(38,0) NOT NULL COMMENT 'Artikel_2 - Hierarchie - Typ - ID: kennzeichnet, ob es sich um eine_2 Hierarchie mit zwei- oder dreistelligen Warengruppen  handelt',
	KUNDE_ID VARCHAR(10) NOT NULL COLLATE 'en-ci' COMMENT 'Warenempfänger (Marktnummer)',
	WG_VERKETT_LIEF NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'Die Warengruppenverkettung gibt an, welche Artikel_2 gemeinsam auf eine_2 Palette gepackt werden.',
	MENGE_LIEF_SOLL_BME NUMBER(18,3) COMMENT 'Die Soll-Liefermenge dient dazu, die ursprüngliche Liefermenge einer Aus- oder Anlieferung festzuhalten. Sie ist berechnet (redundante Speicherung) und in Bestellmengeneinheit dargestellt.',
	MENGE_LIEF_SOLL_KOLLI NUMBER(18,3) COMMENT 'Die Soll-Liefermenge dient dazu, die ursprüngliche Liefermenge einer Aus- oder Anlieferung festzuhalten. Sie bezieht sich auf die Mengeneinheit der Liefermenge (LFIMG). Es handelt sich hier um Kolli!  ',
	BETRAG_LIEF_SOLL NUMBER(18,2) WITH MASKING POLICY #unknown_policy COMMENT 'Aggregation betrag_lief_soll aus besch_lief_det_2',
	MENGE_LIEF_IST_BME NUMBER(18,3) COMMENT 'Menge der Lieferposition, ausgedrückt in Verkaufsmengeneinheiten aus lfimg.',
	MENGE_LIEF_IST_KOLLI NUMBER(18,3) COMMENT 'Anzahl der Kollis der Lieferposition. Ermittlung bei der Kommisionierung',
	BETRAG_LIEF_IST NUMBER(18,2) WITH MASKING POLICY #unknown_policy COMMENT 'Aggregation betrag_lief_ist aus besch_lief_det_2',
	LIEF_PAL_TYP_ID VARCHAR(2) NOT NULL COLLATE 'en-ci' COMMENT 'aus der Tabelle besch_lief_2',
	ANZAHL_POSITION NUMBER(38,0) COMMENT 'Anzahl der Positionen in der besch_lief_det_2',
	WRG_ID VARCHAR(3) NOT NULL COLLATE 'en-ci' DEFAULT 'EUR' COMMENT 'Kurzbezeichnung der Währung, z.Bsp. CZK, EUR',
	MANDANT_ID_KUNDE NUMBER(38,0) NOT NULL DEFAULT 1 COMMENT 'Der Kunde kann zu einem anderen Mandanten als der WUP_2 gehoeren, z.Bsp. Lager aus CZ beliefert Markt in SK',
	VK_NETTO_LIEF_SOLL NUMBER(18,4) NOT NULL DEFAULT 0 COMMENT 'Soll-Liefermenge bewertet zum Verkaufspreis minus MehrWertSteuer',
	VK_NETTO_LIEF_IST NUMBER(18,4) NOT NULL DEFAULT 0 COMMENT 'Ist-Liefermenge bewertet zum Verkaufspreis minus MehrWertSteuer',
	WERBEWARE_ID VARCHAR(1) NOT NULL COLLATE 'en-ci' DEFAULT ' ' COMMENT 'Aus besch_lief_2: Wenn die Bestellart eine_2 Werbebestellart ist. Wertevorrat: W     Werbung       N      Normalware    B      W und N       S      Schnellschuss',
	BESTELLART_ID VARCHAR(4) NOT NULL COLLATE 'en-ci' DEFAULT '    ' COMMENT 'Durch die Einkaufsbelegart kann man z.B. zwischen einer Bestellung, einer Anfrage und einem Lieferplan unterscheiden.',
	HU_STATUS_ID VARCHAR(4) NOT NULL COLLATE 'en-ci' DEFAULT '    ' COMMENT 'Bewegungsstatus der Handling Unit_2',
	ANZAHL_PACKSTUECK NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Aggregation der Gesamtanzahl  der Packstücke für alle Positionen der Lieferung',
	BRTVOL_LADUNG_LITER NUMBER(18,3) NOT NULL DEFAULT 0 COMMENT 'Volumen der Ladung in Litern. Wird aud handling_unit.vol_ladung errechnet',
	BRTVOL_LADUNG_LITER_GEDECKELT NUMBER(18,3) NOT NULL DEFAULT 0 COMMENT 'Volumen der Ladung in Litern. Wird aud handling_unit.vol_ladung errechnet - Deckelung des Volumen der einzelnen HU auf max. 2304 cdm',
	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	AUSLIEFERUNGSGRUPPE_ID VARCHAR(4) COMMENT 'Auslieferungsgruppe aus ZLF_AUSLFEL_2',
	NTVOL_LADUNG_LITER NUMBER(18,3) COMMENT 'Nettovolumen HU in Liter',
	NTVOL_LADUNG_LITER_GEDECKELT NUMBER(18,3) COMMENT 'Nettovolumen HU in Liter (gedeckelt)',
	constraint PK_BESCH_LIEF_WG_WUP primary key (MANDANT_ID, WUP_ID, NB_ID, LAGERORT_ID, DIFF_ID, DAT_LIEF_SOLL, LIEF_TYP_ID, VERTR_BELEG_TYP_ID, WG_ID, ARTHIERTYP_ID, KUNDE_ID, WG_VERKETT_LIEF)
)COMMENT='TP408_LVS - Diese Tabelle enthält die nach Warengruppe, Lagerort und Lieferscheintyp  aggregierten Lieferscheine - MULTISET'
;
